=====INIT

"""The Mininet simulation engine.

:class:`Mininet` owns the instantiated nodes and links and answers the questions
an experiment asks of an emulated network: is a pair of hosts reachable, what
throughput does ``iperf`` report between them, and what is the round-trip time.

Reachability and paths are resolved on a :class:`netsim.graph.WeightedGraph`
built from the links, so higher layers (WiFi, containers, P4, the SDN
controller) can reuse the same routing substrate.
"""

from .graph import WeightedGraph
from .link import Link, TCLink
from .node import Controller, Host, OVSSwitch, Switch
from .packet import Packet, PacketTrace
from .utils import (compute_bottleneck_bw, compute_path_delay,
                    compute_path_loss_rate, generate_ip)


class Mininet:
    """Network emulation engine built from a :class:`netsim.topo.Topo`."""

    def __init__(self, topo=None, switch=OVSSwitch, host=Host,
                 controller=Controller, link=TCLink, ipBase="10.0.0.0/8",
                 build=True, autoSetMacs=False, autoStaticArp=False,
                 waitConnected=False, **params):
        self.topo = topo
        self.switch = switch
        self.host = host
        self.controller = controller
        self.link = link
        self.ipBase = ipBase
        self.ipBaseNum = ".".join(ipBase.split("/")[0].split(".")[:2])
        self.autoSetMacs = autoSetMacs
        self.autoStaticArp = autoStaticArp
        self.waitConnected = waitConnected
        self.params = dict(params)

        self.hosts = []
        self.switches = []
        self.controllers = []
        self.links = []
        self.nameToNode = {}
        self.graph = WeightedGraph()
        self.built = False
        self.started = False
        self.nextIP = 0

        if topo is not None and build:
            self.build()

    # ------------------------------------------------------------------
    # construction
    # ------------------------------------------------------------------
    def addHost(self, name, cls=None, **params):
        """Instantiate a host, register it and return it."""
        cls = cls or self.host
        host = cls(name, **params)
        self.hosts.append(host)
        self._register(host)
        return host

    def addSwitch(self, name, cls=None, **params):
        """Instantiate a switch, register it and return it."""
        cls = cls or self.switch
        switch = cls(name, **params)
        self.switches.append(switch)
        self._register(switch)
        return switch

    def addController(self, name="c0", cls=None, **params):
        """Instantiate a controller, register it and return it."""
        cls = cls or self.controller
        ctrl = cls(name, **params) if not isinstance(name, Controller) else name
        self.controllers.append(ctrl)
        self._register(ctrl)
        return ctrl

    def addLink(self, node1, node2, port1=None, port2=None, cls=None,
                **params):
        """Create a link between two nodes (names or objects) and return it."""
        node1 = self._resolve(node1)
        node2 = self._resolve(node2)
        cls = cls or self.link
        params.pop("isSwitch", None)
        link = cls(node1, node2, port1=port1, port2=port2, **params)
        self.links.append(link)
        self.graph.add_edge(node1.name, node2.name, **link.attrs())
        return link

    def _register(self, node):
        self.nameToNode[node.name] = node
        self.graph.add_node(node.name)
        return node

    def _resolve(self, node):
        if isinstance(node, str):
            return self.nameToNode[node]
        return node

    def build(self):
        """Instantiate the topology: controller, switches, hosts and links."""
        if self.topo is not None:
            self.buildFromTopo(self.topo)
        self.built = True
        return self

    def buildFromTopo(self, topo):
        """Create nodes and links described by ``topo``."""
        if self.controller is not None and not self.controllers:
            self.addController("c0")
        for name in topo.switches():
            opts = topo.nodeInfo(name)
            opts.pop("isSwitch", None)
            cls = opts.pop("cls", None)
            self.addSwitch(name, cls=cls, **opts)
        for name in topo.hosts():
            opts = topo.nodeInfo(name)
            opts.pop("isSwitch", None)
            cls = opts.pop("cls", None)
            self.addHost(name, cls=cls, **opts)
        for node1, node2, opts in topo.links(sort=True, withInfo=True):
            opts = dict(opts)
            cls = opts.pop("cls", None)
            self.addLink(node1, node2, cls=cls, **opts)
        for switch in self.switches:
            for ctrl in self.controllers:
                switch.attach(ctrl)
                if hasattr(ctrl, "add_switch"):
                    ctrl.add_switch(switch)
        return self

    # ------------------------------------------------------------------
    # lifecycle
    # ------------------------------------------------------------------
    def start(self):
        """Start the network: assign host IP addresses."""
        if not self.built:
            self.build()
        for index, host in enumerate(self.hosts):
            if host.ip is None:
                host.setIP(generate_ip(index, base=self.ipBaseNum))
            if self.autoSetMacs and host.mac is None:
                host.setMAC("00:00:00:00:%02x:%02x" %
                            ((index + 1) // 256, (index + 1) % 256))
        for switch in self.switches:
            switch.start(self.controllers)
        self.nextIP = len(self.hosts)
        self.started = True
        return self

    def stop(self):
        """Stop the network."""
        for node in list(self.hosts) + list(self.switches) + list(self.controllers):
            node.stop()
        self.started = False
        return self

    # ------------------------------------------------------------------
    # lookups
    # ------------------------------------------------------------------
    def getNodeByName(self, *args):
        if len(args) == 1:
            return self.nameToNode[args[0]]
        return [self.nameToNode[n] for n in args]

    get = getNodeByName

    def __getitem__(self, key):
        return self.nameToNode[key]

    def __contains__(self, key):
        return key in self.nameToNode

    def __iter__(self):
        return iter(self.nameToNode)

    def __len__(self):
        return len(self.nameToNode)

    def keys(self):
        return list(self.nameToNode)

    def values(self):
        return list(self.nameToNode.values())

    def items(self):
        return list(self.nameToNode.items())

    def total_nodes(self):
        """Number of hosts plus switches (controllers are not data-plane nodes)."""
        return len(self.hosts) + len(self.switches)

    def linksBetween(self, node1, node2):
        """All links connecting the two nodes."""
        n1 = getattr(node1, "name", node1)
        n2 = getattr(node2, "name", node2)
        return [l for l in self.links if l.connects(n1, n2)]

    def isSwitch(self, name):
        node = self.nameToNode.get(getattr(name, "name", name))
        return isinstance(node, Switch)

    # ------------------------------------------------------------------
    # path helpers
    # ------------------------------------------------------------------
    def path(self, src, dst):
        """Shortest node-name path between two nodes, or None."""
        return self.graph.shortest_path(getattr(src, "name", src),
                                        getattr(dst, "name", dst))

    def path_link_attrs(self, path):
        """Per-hop link attribute dicts along a node-name path."""
        attrs = []
        if not path:
            return attrs
        for u, v in zip(path, path[1:]):
            attrs.append(self.graph.get_edge(u, v) or {})
        return attrs

    def path_bandwidth(self, path):
        """Bottleneck bandwidth (Mbps) of a node-name path."""
        bws = [a.get("bw", Link.DEFAULT_BW) for a in self.path_link_attrs(path)]
        return compute_bottleneck_bw(bws)

    def path_delay(self, path):
        """One-way delay (ms) of a node-name path."""
        return compute_path_delay([a.get("delay", 0.0)
                                   for a in self.path_link_attrs(path)])

    def path_loss(self, path):
        """End-to-end loss probability (0-1) of a node-name path."""
        return compute_path_loss_rate([a.get("loss", 0.0) / 100.0
                                       for a in self.path_link_attrs(path)])

    def path_switches(self, path):
        """Switch nodes traversed by a node-name path."""
        out = []
        for name in path or []:
            node = self.nameToNode.get(name)
            if isinstance(node, Switch):
                out.append(node)
        return out

    def switch_overhead_factor(self, path):
        """Combined throughput factor of every switch hop on the path.

        Each switch hop costs ``Switch.FORWARDING_OVERHEAD`` (2%), applied
        multiplicatively so that N switches yield ``0.98 ** N``.
        """
        factor = 1.0
        for switch in self.path_switches(path):
            factor *= (1.0 - getattr(switch, "FORWARDING_OVERHEAD",
                                     Switch.FORWARDING_OVERHEAD))
        return factor

    # ------------------------------------------------------------------
    # measurements
    # ------------------------------------------------------------------
    def _host_list(self, hosts=None):
        if hosts is None:
            return list(self.hosts)
        return [self._resolve(h) for h in hosts]

    def ping(self, hosts=None, timeout=None):
        """Return the packet loss percentage across all ordered host pairs.

        A pair with no path through the topology counts as fully lost; otherwise
        the pair contributes the end-to-end loss probability of its path.
        """
        hosts = self._host_list(hosts)
        lost = 0.0
        packets = 0
        for src in hosts:
            for dst in hosts:
                if src is dst:
                    continue
                packets += 1
                path = self.path(src, dst)
                if not path:
                    lost += 1.0
                else:
                    lost += self.path_loss(path)
        if packets == 0:
            return 0.0
        return 100.0 * lost / packets

    def pingAll(self, timeout=None):
        """Ping between all hosts; returns the loss percentage."""
        return self.ping(self.hosts, timeout=timeout)

    def pingPair(self, hosts=None):
        """Ping between the first two hosts; returns the loss percentage."""
        hosts = self._host_list(hosts)
        return self.ping(hosts[:2])

    def pingFull(self, hosts=None):
        """Per-pair results: ``(src, dst, loss_pct, rtt_ms)`` tuples."""
        hosts = self._host_list(hosts)
        results = []
        for src in hosts:
            for dst in hosts:
                if src is dst:
                    continue
                path = self.path(src, dst)
                if not path:
                    results.append((src, dst, 100.0, None))
                else:
                    results.append((src, dst, 100.0 * self.path_loss(path),
                                    2.0 * self.path_delay(path)))
        return results

    def pingAllFull(self):
        return self.pingFull(self.hosts)

    def iperf(self, hosts=None, l4Type="TCP", udpBw="10M", fmt=None,
              seconds=5, port=5001):
        """Measured bandwidth (Mbps) between two hosts.

        The path's bottleneck bandwidth is reduced by 2% per traversed switch.
        """
        hosts = self._host_list(hosts)
        if len(hosts) < 2:
            if len(self.hosts) < 2:
                return 0.0
            hosts = [self.hosts[0], self.hosts[-1]]
        client, server = hosts[0], hosts[1]
        path = self.path(client, server)
        if not path:
            return 0.0
        bw = self.path_bandwidth(path)
        return bw * self.switch_overhead_factor(path)

    def iperfPair(self, hosts=None):
        """``(server_result, client_result)`` pair, as real Mininet returns."""
        bw = self.iperf(hosts)
        return (bw, bw)

    def rtt(self, src, dst):
        """Round-trip time (ms) between two hosts, or None if unreachable."""
        path = self.path(src, dst)
        if not path:
            return None
        return 2.0 * self.path_delay(path)

    def avg_rtt(self, hosts=None):
        """Average round-trip time (ms) over all distinct host pairs."""
        hosts = self._host_list(hosts)
        total = 0.0
        pairs = 0
        for i, src in enumerate(hosts):
            for dst in hosts[i + 1:]:
                rtt = self.rtt(src, dst)
                if rtt is None:
                    continue
                total += rtt
                pairs += 1
        if pairs == 0:
            return 0.0
        return total / pairs

    def avg_hops(self, hosts=None):
        """Average hop count over all distinct host pairs."""
        hosts = self._host_list(hosts)
        total = 0
        pairs = 0
        for i, src in enumerate(hosts):
            for dst in hosts[i + 1:]:
                path = self.path(src, dst)
                if not path:
                    continue
                total += len(path) - 1
                pairs += 1
        return (total / pairs) if pairs else 0.0

    def send_packet(self, src, dst, size_bytes=1500, protocol="ICMP"):
        """Trace a packet from ``src`` to ``dst`` and return its PacketTrace."""
        src = self._resolve(src)
        dst = self._resolve(dst)
        packet = Packet(src_ip=src.ip or "0.0.0.0", dst_ip=dst.ip or "0.0.0.0",
                        size_bytes=size_bytes, protocol=protocol)
        trace = PacketTrace(packet=packet)
        path = self.path(src, dst)
        if not path:
            return trace
        trace.add_hop(path[0], 0.0)
        for u, v in zip(path, path[1:]):
            attrs = self.graph.get_edge(u, v) or {}
            trace.add_hop(v, attrs.get("delay", 0.0))
        trace.delivered = True
        return trace

"""Utility functions for network simulation."""

import math


def generate_ip(index, base="10.0"):
    """Generate an IP address from a host index."""
    subnet = index // 254
    host = (index % 254) + 1
    return f"{base}.{subnet}.{host}"


def compute_bottleneck_bw(bandwidths):
    """Compute bottleneck bandwidth along a path (minimum of link bandwidths)."""
    if not bandwidths:
        return 0.0
    return min(bandwidths)


def compute_path_delay(delays):
    """Compute one-way delay along a path (sum of link delays)."""
    return sum(delays)


def compute_path_loss_rate(loss_rates):
    """Compute end-to-end loss probability from per-link loss rates (0-1 scale)."""
    success = 1.0
    for lr in loss_rates:
        success *= (1.0 - lr)
    return 1.0 - success


def dbm_to_mw(dbm):
    """Convert dBm to milliwatts."""
    return 10.0 ** (dbm / 10.0)


def mw_to_dbm(mw):
    """Convert milliwatts to dBm."""
    if mw <= 0:
        return -float('inf')
    return 10.0 * math.log10(mw)


def distance_2d(pos1, pos2):
    """Euclidean distance between two 2D points."""
    return math.sqrt((pos1[0] - pos2[0]) ** 2 + (pos1[1] - pos2[1]) ** 2)


def jains_fairness_index(allocations):
    """Compute Jain's fairness index for a list of allocations."""
    if not allocations or all(a == 0 for a in allocations):
        return 0.0
    n = len(allocations)
    sum_x = sum(allocations)
    sum_x2 = sum(x * x for x in allocations)
    return (sum_x ** 2) / (n * sum_x2)
